
(()=>{'use strict';
const cfg=JSON.parse(document.getElementById('published-config')?.textContent||'{}');
const KEY='beyondcv_techmatrix_v84';
const levels=[['','Noch nicht eingeordnet'],['strategy','Strategisch verantwortet'],['operational','Operativ eingesetzt'],['integrated','In Projekten integriert / begleitet']];
const defaults=JSON.parse(document.getElementById('tech-matrix-data').textContent);
const groups=[...new Set(defaults.map(x=>x.group))];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=structuredClone(defaults);
try{const saved=JSON.parse(localStorage.getItem(KEY));if(Array.isArray(saved)&&saved.length&&saved.every(x=>x&&typeof x.name==='string'&&typeof x.group==='string')){const map=new Map(saved.map(x=>[x.name,x]));entries=defaults.map(x=>({...x,...map.get(x.name)}));}}catch(e){console.warn('Technologie-Matrix: lokale Daten nicht lesbar',e)}
const btn=document.createElement('button');btn.id='tech-matrix-launch';btn.type='button';btn.textContent='TECH-STACK';btn.setAttribute('aria-haspopup','dialog');
const nav=document.querySelector('header.top nav');if(nav)nav.insertBefore(btn,document.getElementById('careerBtn')||nav.firstChild);
const root=document.createElement('section');root.id='tech-matrix';root.hidden=true;root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Technologie-Matrix');
root.innerHTML=`<div class="tm-shell"><div class="tm-head"><div><span class="tm-kicker">Beyond the CV / Technology</span><h2>Mein Technologie-Stack.</h2><p>Technologien nach Einsatzbereich – mit einer transparenten Unterscheidung zwischen strategischer Verantwortung, operativer Anwendung und Projektintegration. Die Einstufungen kannst du selbst ergänzen; unbelegte Erfahrungsgrade werden nicht behauptet.</p></div><button type="button" class="tm-close" id="tm-close">✕ Schließen</button></div><div class="tm-controls"><input id="tm-search" type="search" placeholder="Technologie suchen …" aria-label="Technologie suchen"><select id="tm-group" aria-label="Einsatzbereich filtern"><option value="">Alle Einsatzbereiche</option>${groups.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}</select><select id="tm-level" aria-label="Erfahrungsgrad filtern">${[['','Alle Erfahrungsgrade'],...levels.map(x=>[x[0]||'unassigned',x[1]])].map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select></div><div class="tm-stats" id="tm-stats" aria-live="polite"></div><div id="tm-results"></div><div class="tm-actions" id="tm-actions"><button type="button" class="tm-primary" id="tm-save">Änderungen lokal speichern</button><button type="button" id="tm-export">JSON-Backup exportieren</button><button type="button" id="tm-import">JSON importieren</button><input type="file" accept="application/json,.json" id="tm-file" hidden><button type="button" id="tm-reset">Einstufungen zurücksetzen</button></div><p class="tm-note">Hinweis: Diese Matrix speichert Änderungen zunächst nur im aktuellen Browser. Der bestehende HTML-Veröffentlichungsexport übernimmt sie noch nicht automatisch. Für die spätere Veröffentlichung die JSON-Datei sichern. Die Bearbeitung ist kein geschützter Online-Editor.</p></div>`;
document.body.append(root);
const $=id=>document.getElementById(id);
let previous=null;
function open(){previous=document.activeElement;root.hidden=false;document.body.style.overflow='hidden';render();$('tm-search').focus();}
function close(){root.hidden=true;document.body.style.overflow='';if(previous&&previous.isConnected)previous.focus();}
btn.addEventListener('click',open);$('tm-close').addEventListener('click',close);
root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const focus=[...root.querySelectorAll('button:not([hidden]),input:not([hidden]),select')].filter(x=>!x.disabled&&x.getClientRects().length);if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function render(){const search=$('tm-search').value.trim().toLocaleLowerCase('de'),group=$('tm-group').value,level=$('tm-level').value;
const visible=entries.filter(x=>(!search||`${x.name} ${x.note}`.toLocaleLowerCase('de').includes(search))&&(!group||x.group===group)&&(!level||(level==='unassigned'?!x.level:x.level===level)));
$('tm-stats').innerHTML=`<div class="tm-stat"><strong>${entries.length}</strong> Technologien</div><div class="tm-stat"><strong>${entries.filter(x=>x.level).length}</strong> eingeordnet</div><div class="tm-stat"><strong>${entries.filter(x=>!x.level).length}</strong> offen</div><div class="tm-stat"><strong>${visible.length}</strong> angezeigt</div>`;
$('tm-results').innerHTML=visible.length?groups.map(g=>{const subset=visible.filter(x=>x.group===g);if(!subset.length)return '';return `<section class="tm-group"><h3>${esc(g)} <span style="color:#83c7dd;font-weight:400">(${subset.length})</span></h3><div class="tm-grid">${subset.map(x=>`<article class="tm-entry" data-id="${esc(x.id)}"><div class="tm-entry-title">${esc(x.name)}</div><label>Meine Erfahrung<select data-field="level" aria-label="Erfahrungsgrad ${esc(x.name)}">${levels.map(([v,l])=>`<option value="${esc(v)}" ${x.level===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label>Konkreter Einsatz / Projektbezug<input data-field="note" maxlength="240" value="${esc(x.note)}" placeholder="z. B. Projekt, Aufgabe, Zeitraum" aria-label="Projektbezug ${esc(x.name)}"></label></article>`).join('')}</div></section>`}).join(''):'<p class="tm-empty">Keine passenden Technologien gefunden.</p>';
}
$('tm-search').addEventListener('input',render);$('tm-group').addEventListener('change',render);$('tm-level').addEventListener('change',render);
$('tm-results').addEventListener('change',e=>{const field=e.target.dataset.field;if(!field)return;const row=e.target.closest('[data-id]');const item=entries.find(x=>x.id===row?.dataset.id);if(item){item[field]=e.target.value;if(field==='level')render();}});
$('tm-results').addEventListener('input',e=>{if(e.target.dataset.field!=='note')return;const item=entries.find(x=>x.id===e.target.closest('[data-id]')?.dataset.id);if(item)item.note=e.target.value;});
function save(){try{localStorage.setItem(KEY,JSON.stringify(entries));return true}catch(e){alert('Speichern im Browser nicht möglich. Bitte JSON-Backup exportieren.');return false}}
$('tm-save').addEventListener('click',()=>{if(save())alert('Technologie-Matrix lokal gespeichert. Für die Veröffentlichung bitte zusätzlich JSON exportieren.');});
$('tm-export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({version:1,entries},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Beyond-the-CV-Technologie-Matrix.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});
$('tm-import').addEventListener('click',()=>$('tm-file').click());
$('tm-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Datei zu groß');const raw=JSON.parse(await file.text());if(!Array.isArray(raw.entries))throw Error('Ungültiges Format');const map=new Map(raw.entries.filter(x=>x&&typeof x.name==='string'&&levels.some(([v])=>v===x.level)&&typeof x.note==='string').map(x=>[x.name,x]));entries=defaults.map(x=>{const y=map.get(x.name);return y?{...x,level:y.level,note:y.note.slice(0,240)}:x});save();render();alert('Technologie-Matrix importiert.');}catch(err){alert('Import fehlgeschlagen: '+err.message)}finally{e.target.value='';}});
$('tm-reset').addEventListener('click',()=>{if(!confirm('Alle Erfahrungsstufen und Projektnotizen zurücksetzen?'))return;entries=structuredClone(defaults);save();render();});
})();
